interface Product {
  readonly id: string;
  title: string;
  price: number;
  tag?: string;
}

type CartLine = Product & { qty: number };

function lineTotal(line: CartLine): number {
  return line.price * line.qty;
}

const line: CartLine = {
  id: "p1",
  title: "Книга",
  price: 500,
  qty: 2,
};

console.log(lineTotal(line));
